/** Evaluate the WebGL blend equation at a line fragment, independently of the canvas compositor. */
function linePixelContext() {
  let pixel = [0, 0, 0, 0];
  let color = [0, 0, 0, 0];
  let factors = [1, 0, 1, 0];
  const gl = {
    canvas: { width: 1280, height: 780 },
    ZERO: 0, ONE: 1, SRC_ALPHA: 2, ONE_MINUS_SRC_ALPHA: 3,
    LINES: 4, POINTS: 5, COMPILE_STATUS: 6, LINK_STATUS: 7,
    ARRAY_BUFFER: 8, ELEMENT_ARRAY_BUFFER: 9, UNSIGNED_SHORT: 10, UNSIGNED_INT: 11,
    getShaderParameter: () => true,
    getProgramParameter: () => true,
    getExtension: () => ({}),
    getAttribLocation: () => 0,
    getUniformLocation: (_program, name) => name,
    clear: () => { pixel = [0, 0, 0, 0]; },
    uniform4f: (name, ...values) => { if (name === "color") color = values; },
    blendFunc: (source, destination) => { factors = [source, destination, source, destination]; },
    blendFuncSeparate: (...values) => { factors = values; },
    drawElements: () => {
      const factor = (value) => [0, 1, color[3], 1 - color[3]][value];
      pixel = pixel.map((destination, channel) => {
        const pair = channel === 3 ? 2 : 0;
        return color[channel] * factor(factors[pair]) + destination * factor(factors[pair + 1]);
      });
    },
  };
  return {
    gl: new Proxy(gl, { get: (target, key) => key in target ? target[key] : () => ({}) }),
    pixel: () => pixel,
  };
}

for (const [theme, edge, background] of [
  ["light", [183 / 255, 198 / 255, 207 / 255, 0.26], [1, 1, 1]],
  ["dark", [54 / 255, 86 / 255, 95 / 255, 0.26], [10 / 255, 24 / 255, 29 / 255]],
]) {
  test(`indexed GPU edges preserve opacity and visible ${theme} compositing across zoom and index sizes`, () => {
    const context = linePixelContext();
    const renderer = new IndexedGraphGl(context.gl);
    try {
      for (const size of [500, 1000, 65536]) {
        renderer.upload(new GraphScene(fixture(size)));
        for (const k of [0.04, 0.16, 1, 4]) {
          renderer.draw({ x: 0, y: 0, k }, 1280, 780, 1, 1, { edge, node: [0.4, 0.7, 0.6, 0.9] });
          const pixel = context.pixel();
          assert.ok(Math.abs(pixel[3] - edge[3]) < 1e-12, `edge opacity at ${size} nodes, zoom ${k}`);
          for (let channel = 0; channel < 3; channel++) {
            const expected = edge[channel] * edge[3] + background[channel] * (1 - edge[3]);
            const composited = Math.min(1, pixel[channel] + background[channel] * (1 - pixel[3]));
            assert.ok(Math.abs(composited - expected) < 1e-12,
              `${theme} channel ${channel} at ${size} nodes, zoom ${k}: ${composited} != ${expected}`);
          }
          for (const alpha of [0, 0.6, 1]) {
            renderer.draw({ x: 0, y: 0, k }, 1280, 780, 1, 1, {
              edge: [edge[0], edge[1], edge[2], alpha], node: [0.4, 0.7, 0.6, 0.9],
            });
            const variedPixel = context.pixel();
            assert.ok(Math.abs(variedPixel[3] - alpha) < 1e-12, `${theme} opacity ${alpha} at zoom ${k}`);
            for (let channel = 0; channel < 3; channel++) {
              const expected = edge[channel] * alpha + background[channel] * (1 - alpha);
              const composited = Math.min(1, variedPixel[channel] + background[channel] * (1 - variedPixel[3]));
              assert.ok(Math.abs(composited - expected) < 1e-12,
                `${theme} channel ${channel}, opacity ${alpha}: ${composited} != ${expected}`);
            }
          }
        }
      }
    } finally { renderer.dispose(); }
  });
}
